Lemma proof_of_OSFlagPend_return_wit_6 : flag_pend_goal.OSFlagPend_return_wit_6.
Proof.
left; intros.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  assert (Hdecode : decode_flag_wait_mode (osKernelConfig sg) (Z.land original_mode 127) = None).
  { destruct PreH21 as [Hmode Hconsume].
    unfold decode_flag_wait_mode; rewrite <- Hmode.
    rewrite (proj2 (Z.eqb_neq joined_mode 2) ltac:(lia)).
    rewrite (proj2 (Z.eqb_neq joined_mode 3) ltac:(lia)).
    destruct (cfgFlagClearWait (osKernelConfig sg)); [|reflexivity].
    rewrite (proj2 (Z.eqb_neq joined_mode 0) ltac:(lia)).
    rewrite (proj2 (Z.eqb_neq joined_mode 1) ltac:(lia)); reflexivity. }
  pose proof (flag_pend_first_invalid_mode sg i requested original_mode delay acquired Hdecode) as Hfirst.
  sep_apply_l_atomic (flag_pend_first_return_public_post environment critical local acquired_local
    sg caller call original_mode mask i pgrp0 requested delay before observed entered_caller entered
    joined_saved acquired release_heap errp X
    PreH6 PreH7 PreH8 PreH9 PreH11 PreH12 PreH13 PreH14 PreH15 Hfirst).
  entailer!.
Qed.


