  destruct PreH11 as [Hcfg [Hptr [Hrequested [Hmode [Hdelay [Hsource Hsafe]]]]]].
  assert (Hreturn : flag_pend_return_safe 0 1 before X).
  { eapply flag_pend_caller_safe_return; [|exact Hsafe].
    destruct caller; cbn [flag_pend_caller_program].
    - eapply flag_pend_program_bad_type; [exact PreH10|exact PreH5|exact PreH4|exact PreH2|].
      intro Heq; apply PreH1; unfold flag_pend_group_type; rewrite Heq; reflexivity.
    - unfold flag_pend_view_program.
      rewrite (proj2 (Z.eqb_neq _ _) PreH10), (proj2 (Z.ltb_ge _ _) PreH5),
