      exists observed; split; [exact PreH2|].
      assert (Hbad : observed.(flagImageType) <> 5).
      { intro Heq; apply PreH1; unfold flag_pend_group_type; rewrite Heq; reflexivity. }
      rewrite (proj2 (Z.eqb_neq _ _) Hbad); cbn; auto. }
  assert (Hsame : flag_pend_same_caller caller caller).
