  destruct Hentry as [Hconfig [Haddress [Hrequested [Hmode [Hdelay [Hsource Hsafe]]]]]].
  assert (Hfirst : flag_pend_first_registration original_mode call before call before).
  { unfold flag_pend_first_registration; intros [Hvalidmode|Hentry].
    - apply flag_pend_entry_fresh_observation.
      destruct caller as [actual|view key].
      + destruct Hsource as [Heq Hdomain].
        exact (proj1 (Hdomain Hp Hint Hlock observed Hlookup Htype Hvalidmode)).
      + destruct Hsource as [Hinterrupt Hdomain].
        exfalso; exact (Hdomain Hp Hint Hlock observed Hlookup Htype Hvalidmode).
    - apply flag_pend_entry_fresh_observation; exact Hentry. }
  sep_apply_l_atomic (proj1 (flag_pend_caller_world_split environment local sg caller mask before)).
  unfold FlagPendActiveCallerControl.flag_pend_caller_counters_zero,
    FlagPendCallerControl.flag_pend_caller_counters_zero.
  destruct caller as [actual|view key].
  - destruct Hsource as [Heq Hdomain]; subst actual.
    unfold flag_pend_caller_control, flag_pend_call_control, flag_pend_caller_save_input,
      flag_pend_active_save_input, os_sched_fields_save_input, flag_pend_first_observation.
