Lemma proof_of_OSFlagPend_which_implies_wit_11 : flag_pend_goal.OSFlagPend_which_implies_wit_11.
Proof.
left; intros.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  assert (Hinput_counters : flag_pend_caller_save_input environment critical local
    (flag_pend_first_observation original_mode call before) sg caller call mask before |--
    coq_prop (FlagPendActiveCallerControl.flag_pend_caller_counters_zero
      (flag_pend_first_observation original_mode call before) caller before)).
  { destruct caller as [actual|view key].
    - unfold flag_pend_caller_save_input, flag_pend_active_save_input,
        os_sched_fields_save_input, FlagPendActiveCallerControl.flag_pend_caller_counters_zero,
        FlagPendCallerControl.flag_pend_caller_counters_zero.
      Intros.
      sep_apply_l_atomic (FlagPendCounterEntry.flag_pend_fields_guard_counters_zero
        sg before PreH2 PreH3).
      Intros; entailer!.
    - unfold FlagPendActiveCallerControl.flag_pend_caller_counters_zero,
        FlagPendCallerControl.flag_pend_caller_counters_zero; entailer!. }
  assert (Hopen : FlagPendActiveCaller.flag_pend_selected_caller_save_output
    environment critical local (flag_pend_first_observation original_mode call before)
    sg caller call mask before first_heap cpu_sr |--
    EX returned_caller returned acquired next_local,
      coq_prop (FlagPendActiveCaller.flag_pend_caller_save_observation environment critical
        (flag_pend_first_observation original_mode call before) sg caller call
        returned_caller returned mask cpu_sr before acquired /\
        interrupt_saved_value mask cpu_sr /\
        FlagPendActiveCaller.flag_pend_caller_endpoint_observations environment
          (flag_pend_first_observation original_mode call before) sg caller call before returned acquired /\
        FlagPendActiveCallerControl.flag_pend_caller_counters_zero
          (flag_pend_first_observation original_mode call before) returned_caller acquired) &&
      flag_pend_caller_restore_input environment critical next_local
        (flag_pend_first_observation original_mode call before) sg returned_caller returned
        cpu_sr acquired acquired).
  { intros heap [rc [returned [acquired [next_local Hevent]]]].
    destruct (FlagPendActiveCaller.flag_pend_save_event_resources
      _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hevent) as [Hsaved [Hbefore Hafter]].
    pose proof (FlagPendActiveCaller.flag_pend_save_event_observation
      _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hevent) as Hsave.
    assert (Hendpoint : FlagPendActiveCaller.flag_pend_caller_endpoint_observations environment
      (flag_pend_first_observation original_mode call before) sg caller call before returned acquired).
    { intro Hnonempty.
      pose proof (FlagPendActiveCaller.flag_pend_save_event_nonempty
        _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hnonempty Hevent)
        as [_ [_ [_ [_ Hsource]]]].
      exact (proj1 (CompletedCallerSource.flag_pend_selected_completed_source_endpoints
        _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hsource)). }
    exists rc, returned, acquired, next_local; split; [|exact Hafter].
    split; [exact Hsave|]. split; [exact Hsaved|]. split; [exact Hendpoint|].
    eapply FlagPendActiveCallerControl.flag_pend_caller_save_counters_zero;
      [exact Hsave|exact Hendpoint|exact (Hinput_counters first_heap Hbefore)]. }
  sep_apply_l_atomic Hopen.
  Intros entered_caller entered acquired acquired_local.
  match goal with
  | H : FlagPendActiveCaller.flag_pend_caller_save_observation _ _ _ _ _ _ _ _ _ _ _ _ /\ _ |- _ =>
    destruct H as [Hsave [Hsaved [Hendpoint Hcounters]]]
  end.
  assert (Hacquired_entry : FlagPendEntryControl.flag_pend_active_entry sg
    (flag_pend_first_observation original_mode call before) acquired).
  { destruct PreH6 as [_ [_ [_ [_ [_ [Hsource Hsafe]]]]]].
    eapply flag_pend_first_caller_endpoint_entry;
      [exact Hsource|exact PreH1|exact PreH2|exact PreH3|exact PreH4|exact PreH5|
       exact PreH9|exact Hendpoint]. }
  Exists acquired_local entered_caller entered acquired.
  destruct entered_caller;
    unfold flag_pend_caller_fields_restore_input, flag_pend_caller_restore_input,
      flag_pend_active_restore_input, flag_pend_first_observation;
    entailer!.
Qed.


