Lemma proof_of_OSFlagPend_entail_wit_1_1 : flag_pend_goal.OSFlagPend_entail_wit_1_1.
Proof.
  pre_process.
  retain_original_public_entry__active_tick.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  subst perr_pre timeout_pre wait_type_pre flags_pre pgrp_pre.
  assert (Hmode : 0 <= original_mode < 256).
  { match goal with H : flag_pend_public_entry _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ =>
      pose proof H as Hentry_bounds; unfold flag_pend_public_entry in Hentry_bounds; tauto end. }
  assert (Hobserved_range : 0 <= flag_pend_group_type observed < 256).
  { eapply (flag_pend_group_type_in_range__saved_mode_join sg before i observed); eassumption. }
  assert (Hobserved : flag_pend_group_type observed = 5).
  { match goal with H : unsigned_last_nbits (flag_pend_group_type observed) 32 = 5 |- _ =>
      rewrite unsigned_last_nbits_eq in H; [exact H | change (0 <= flag_pend_group_type observed < 4294967296); lia] end. }
  assert (Hparameters : flag_pend_mode_parameters original_mode original_mode 0).
  { apply flag_pend_mode_parameters_from_c_tests__saved_mode_join; [exact Hmode |].
    left; repeat split; try reflexivity; assumption. }
  repeat match goal with H : context [unsigned_last_nbits original_mode 32] |- _ =>
    rewrite unsigned_last_nbits_eq in H by (change (0 <= original_mode < 4294967296); lia) end.
  Left.
  entailer!.
Qed.

