Lemma proof_of_OSFlagPend_entail_wit_3_1 : flag_pend_goal.OSFlagPend_entail_wit_3_1.
Proof.
  unfold OSFlagPend_entail_wit_3_1; left; intros.
  retain_original_public_entry__active_tick.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  assert (Hentry_counter_bounds :
    flag_pend_group_current_frame sg acquired current_tid current_task i protected_image |--
    coq_prop (0 <= os_sched_ints acquired /\ 0 <= os_sched_locks acquired)).
  { unfold flag_pend_group_current_frame, UCOS2_raw_rep_missing_task_storage_sched_flag,
      interrupt_inv, interrupt_in_range, os_sched_ints, os_sched_locks; entailer!. }
  prop_apply_p Hentry_counter_bounds.
  Intros.
  try rename H into Hentry_int_nonnegative.
  try rename H0 into Hentry_lock_nonnegative.
  pose proof Hlegacy_entry__active_tick as Hpublic.
  destruct Hpublic as [Hcfg [Haddress [Hrequested [Hmode_range Hpublic_rest]]]].
  assert (Hen : (osKernelConfig sg).(cfgFlagEnabled) = true) by (rewrite Hcfg; reflexivity).
  assert (Hwidth : (osKernelConfig sg).(cfgFlagBits) = 16) by (rewrite Hcfg; reflexivity).
  assert (Hvalidmode : flag_pend_valid_mode original_mode).
  { unfold flag_pend_valid_mode; rewrite <- (proj1 PreH26); lia. }
  destruct (flag_pend_acquired_task_stage__immediate_set
    environment critical sg caller call mask i pgrp0 requested original_mode delay before X
    entered_caller entered joined_saved acquired Hlegacy_entry__active_tick PreH7 PreH6 PreH21 Hvalidmode)
    as [Hcaller [Hprefix Hstage]].
  subst entered_caller.
  assert (Hbits : 0 <= flagImageBits protected_image < 65536).
  { destruct PreH24 as [_ [_ [_ [_ [_ [_ [_ [Hflags _]]]]]]]].
    unfold valid_flag_configuration in Hflags; rewrite Hen in Hflags.
    destruct Hflags as [_ [_ [Himages _]]].
    pose proof (proj1 (Himages i protected_image PreH25)) as Hb.
    unfold flag_word_in_range in Hb; rewrite Hwidth in Hb; exact Hb. }
  assert (Hdecode : decode_flag_wait_mode (osKernelConfig sg)
      (Z.land original_mode 127) = Some FlagSetAll).
  { assert (Hjoined : decode_flag_wait_mode (osKernelConfig sg) joined_mode = Some FlagSetAll).
    { rewrite <- PreH28; reflexivity. }
    exact (eq_trans (f_equal (decode_flag_wait_mode (osKernelConfig sg)) (eq_sym (proj1 PreH26))) Hjoined). }
  set (ready := Z.land (flag_pend_group_bits protected_image)
    (unsigned_last_nbits requested 16)).
  assert (Eready : flag_ready_bits (osKernelConfig sg)
      (flagImageBits protected_image) requested FlagSetAll = ready).
  { unfold ready, flag_ready_bits, flag_word, flag_pend_group_bits, unsigned_last_nbits.
    rewrite Hwidth; change ((Z.land (flagImageBits protected_image) requested) mod 65536 =
      Z.land (flagImageBits protected_image) (requested mod 65536)).
    symmetry; apply flag_pend_word_land_eq__immediate_set; exact Hbits. }
