          (flag_pend_pool_set_bits (FlagState acquired) i protected_image
            (flag_consume_bits (osKernelConfig sg) (flagImageBits protected_image) ready FlagSetAll))
          acquired else acquired) current_tid (flag_pend_task_set_ready_flags current_task ready)))
      Hfirst false Hbit) as Hselected.
    unfold released, flags; rewrite replace_FlagS_put_back; exact Hselected. }
  assert (Hstage_after : flag_pend_task_stage entered released).
  { unfold released; eapply flag_pend_ready_flags_stage__immediate_set; eauto. }
  assert (Hregistration_after : flag_pend_first_registration original_mode call before entered released).
  { intros _; unfold released; eapply flag_pend_ready_flags_registration__immediate_set.
    - apply PreH21; left; exact Hvalidmode.
    - destruct Hstage as [_ [_ [_ [node [Hcurrent [Hgen Hclean]]]]]].
      exists node; auto.
    - exact PreH1. }
  assert (Himage : flagImages flags i = Some (flag_image_set_bits protected_image bits)).
  { unfold flags, bits; rewrite PreH25; f_equal; destruct protected_image; reflexivity. }
  assert (Hother : forall j, j <> i ->
