  { intros; reflexivity. }
  assert (Hnodes : flagWaitNodes (FlagState acquired) = flagWaitNodes flags) by reflexivity.
  assert (Hfree : flagFree (FlagState acquired) = flagFree flags) by reflexivity.
  assert (Hpgrp : pgrp0 = flag_pool_addr sg i).
  { destruct Haddress as [Hzero|[_ Hpgrp]]; [contradiction|exact Hpgrp]. }
  destruct PreH8 as [Hblock [Hunlink [Htype_addr [Hbits_addr [Hready_addr Hlayout_rest]]]]].
  destruct PreH10 as [Hglob Hcurrent_addr].
  rewrite Htype_addr, Hbits_addr, Hready_addr, Hcurrent_addr.
  fold ready.
  assert (Hreturned_entry : FlagPendEntryControl.flag_pend_active_entry sg
    (flag_pend_first_observation original_mode call before) released).
  { apply FlagPendEntryControl.FlagPendEntryFirst; intros _.
    match goal with
    | Hstage : flag_pend_task_stage _ released |- _ => exact (proj1 (proj2 Hstage))
    end. }
  assert (Hreturned_counters : os_sched_ints released = 0 /\ os_sched_locks released = 0).
  { eapply FlagPendCounterEntry.flag_pend_first_critical_counters_zero; [eassumption| |].
    all: match goal with
    | Hprefix : flag_pend_saved_prefix _ _ _ _ _ _ _ _ _ _ ?acquired_state |- _ =>
      destruct Hprefix as [_ [Hint [Hlock [_ [_ [_ [_ Heq]]]]]]];
      unfold os_sched_ints, os_sched_locks in *; rewrite Heq in Hint, Hlock; lia
    end. }
  destruct Hreturned_counters as [Hreturned_ints Hreturned_locks].
