Lemma proof_of_OSFlagPend_entail_wit_5 : flag_pend_goal.OSFlagPend_entail_wit_5.
Proof.
  left; intros.
  retain_original_public_entry__active_tick.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  destruct PreH6 as [Hvalid [Hready [Hidle [Hnonidle Havailable]]]].
  destruct PreH8 as [Hfresh [Hkey [Hprotocol [Hnode [Hgroup [Hmask Hmode]]]]]].
  assert (Hflags : valid_flag_state sg (FlagState acquired)).
  { unfold UCOS2_state_inv, UCOS2_state_inv_with_ready,
      valid_flag_configuration in Hvalid.
    assert (Hconfig : osKernelConfig sg = selected_kernel_configuration)
      by exact (proj1 Hlegacy_entry__active_tick).
    rewrite Hconfig in Hvalid; cbn [selected_kernel_configuration cfgFlagEnabled] in Hvalid; tauto. }
  sep_apply_l_atomic (flag_pend_block_fields_wait_outcome sg acquired call entered waiter old_task group protected_image delay
    Hfresh Hkey Hidle Hnonidle Hvalid Hflags Hprotocol).
  Intros flags.
  assert (Hconfig : osKernelConfig sg = selected_kernel_configuration)
    by exact (proj1 Hlegacy_entry__active_tick).
  destruct PreH7 as [mode [Hdecode Hunsatisfied]].
  assert (Hdecoded : decode_flag_wait_mode (osKernelConfig sg)
    (encode_flag_wait_mode (flagWaitMode waiter)) = Some (flagWaitMode waiter)).
  { apply decode_encode_flag_wait_mode; rewrite Hconfig; reflexivity. }
  rewrite Hmode, (proj1 PreH9), Hdecode in Hdecoded.
  inversion Hdecoded; subst mode.
  assert (Hused : flagUsed (FlagState acquired) (flagGroup waiter) = Some group)
    by (unfold flag_block_call_protocol in Hprotocol; tauto).
  assert (Himage : flagImages (FlagState acquired) i = Some protected_image).
  { rewrite <- Hgroup; unfold flag_block_call_protocol in Hprotocol; tauto. }
  assert (Htype : flagImageType protected_image = 5).
  { destruct Hflags as [_ [_ [_ [Hused_valid _]]]].
    destruct (Hused_valid _ _ Hused) as [_ [_ [_ [actual [Hactual [Htype _]]]]]].
    rewrite Hgroup, Himage in Hactual; inversion Hactual; subst actual; exact Htype. }
  assert (Hwaiting : flag_pend_first_waiting sg i requested original_mode delay
    acquired (flagNodeAddr waiter) (flag_block_state acquired waiter flags old_task delay)).
  { unfold flag_pend_first_waiting.
    eapply flag_pend_first_block with (mode := flagWaitMode waiter)
      (image := protected_image) (old := old_task) (group := group); try eassumption.
    - reflexivity.
    - exact (proj2 H). }
