    acquired waiter flags old_task delay) as [Hstacks Hfields].
  assert (Hcaps : os_sched_fields_capsules environment acquired_local acquired |--
    os_sched_fields_capsules environment acquired_local
      (flag_block_state acquired waiter flags old_task delay)).
  { unfold os_sched_fields_capsules; rewrite Hstacks.
    apply kernel_saved_continuation_publication_spec.kernel_saved_continuation_map_reindex.
    intros key payload updated Hlookup Hupdated Hgen.
    exact (Hfields _ _ Hupdated Hold). }
  assert (Hblocked_guards :
    os_sched_ints (flag_block_state acquired waiter flags old_task delay) <= 0 /\
    os_sched_locks (flag_block_state acquired waiter flags old_task delay) <= 0).
  { change (os_sched_ints acquired <= 0 /\ os_sched_locks acquired <= 0).
    destruct PreH5 as [_ [Hint [Hlock [_ [_ [_ [_ Heq]]]]]]].
    unfold os_sched_ints, os_sched_locks in *; rewrite <- Heq; split; assumption. }
  sep_apply_l_atomic (FlagPendCounterEntry.flag_pend_fields_guard_counters_zero
    sg (flag_block_state acquired waiter flags old_task delay)
    (proj1 Hblocked_guards) (proj2 Hblocked_guards)).
  Intros.
  pose proof (FlagPendEntryControl.flag_pend_waiting_entry_control sg call (&("node"))
    entered (flag_block_state acquired waiter flags old_task delay) Havailable_after) as Hblocked_entry.
  unfold flag_pend_block_callee_frame, flag_pend_masked_control.
  Intros.
  assert (Hcoverage_after : task_stack_coverage_spec.task_stack_live_coverage
    (TskState (flag_block_state acquired waiter flags old_task delay))
    (task_stack_call_active_key entered)).
  { eapply task_stack_coverage_spec.task_stack_live_coverage_used_map_frame
      with (before := TskState acquired); [|exact Hstacks|eassumption].
    intros slot updated Hupdated.
    destruct (Hfields _ _ Hupdated Hold) as [previous [Hprevious [Hgen Hsp]]].
    exists previous; split; [exact Hprevious|symmetry; exact Hgen]. }
  sep_apply_l_atomic Hcaps.
  Exists (flag_block_state acquired waiter flags old_task delay).
  rewrite Hnode in Hwaiting; rewrite Hnode.
  unfold flag_pend_caller_restore_input, flag_pend_active_restore_input,
    os_sched_fields_restore_input.
  entailer!.
Qed.

Lemma proof_of_OSFlagPend_entail_wit_7_1 : flag_pend_goal.OSFlagPend_entail_wit_7_1.
Proof.
  unfold OSFlagPend_entail_wit_7_1; left; intros.
  retain_original_public_entry__active_tick.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  assert (Hentry_counter_bounds :
    flag_pend_group_current_frame sg acquired current_tid current_task i protected_image |--
    coq_prop (0 <= os_sched_ints acquired /\ 0 <= os_sched_locks acquired)).
  { unfold flag_pend_group_current_frame, UCOS2_raw_rep_missing_task_storage_sched_flag,
      interrupt_inv, interrupt_in_range, os_sched_ints, os_sched_locks; entailer!. }
  prop_apply_p Hentry_counter_bounds.
  Intros.
  try rename H into Hentry_int_nonnegative.
  try rename H0 into Hentry_lock_nonnegative.
  pose proof Hlegacy_entry__active_tick as Hpublic.
