  assert (Hwidth : (osKernelConfig sg).(cfgFlagBits) = 16) by (rewrite Hcfg; reflexivity).
  assert (Hvalidmode : flag_pend_valid_mode original_mode).
  { unfold flag_pend_valid_mode; rewrite <- (proj1 PreH26); lia. }
  destruct (flag_pend_acquired_task_stage__immediate_set
    environment critical sg caller call mask i pgrp0 requested original_mode delay before X
    entered_caller entered joined_saved acquired Hlegacy_entry__active_tick PreH7 PreH6 PreH21 Hvalidmode)
    as [Hcaller [Hprefix Hstage]].
  subst entered_caller.
  assert (Hbits : 0 <= flagImageBits protected_image < 65536).
  { destruct PreH24 as [_ [_ [_ [_ [_ [_ [_ [Hflags _]]]]]]]].
    unfold valid_flag_configuration in Hflags; rewrite Hen in Hflags.
    destruct Hflags as [_ [_ [Himages _]]].
    pose proof (proj1 (Himages i protected_image PreH25)) as Hb.
    unfold flag_word_in_range in Hb; rewrite Hwidth in Hb; exact Hb. }
  assert (Hdecode : decode_flag_wait_mode (osKernelConfig sg)
      (Z.land original_mode 127) = Some FlagSetAny).
  { assert (Hjoined : decode_flag_wait_mode (osKernelConfig sg) joined_mode = Some FlagSetAny).
    { rewrite <- PreH29; reflexivity. }
    exact (eq_trans (f_equal (decode_flag_wait_mode (osKernelConfig sg)) (eq_sym (proj1 PreH26))) Hjoined). }
  set (ready := Z.land (flag_pend_group_bits protected_image)
    (unsigned_last_nbits requested 16)).
  assert (Eready : flag_ready_bits (osKernelConfig sg)
      (flagImageBits protected_image) requested FlagSetAny = ready).
  { unfold ready, flag_ready_bits, flag_word, flag_pend_group_bits, unsigned_last_nbits.
