Lemma proof_of_OSFlagPend_entail_wit_8_1 : flag_pend_goal.OSFlagPend_entail_wit_8_1.
Proof.
  left; intros.
  retain_original_public_entry__active_tick.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  pose proof Hlegacy_entry__active_tick as Hpublic.
  destruct Hlegacy_entry__active_tick as [Hconfig [Hslot [Hrequested [Hmode_range [Hdelay [Hsource Hsafe]]]]]].
  assert (Hvalid_mode : flag_pend_valid_mode original_mode).
  { unfold flag_pend_valid_mode; destruct PreH24 as [Hnormalized _]; lia. }
  assert (Hcaller : caller = FlagPendTaskCaller call).
  { destruct caller as [actual|view active].
    - destruct Hsource as [-> _]; reflexivity.
    - destruct Hsource as [_ Hreject].
      exfalso; eapply Hreject; eauto. }
  subst caller.
  destruct Hsource as [_ Hdomain].
  destruct (Hdomain PreH10 PreH11 PreH12 observed PreH14 PreH15 Hvalid_mode)
    as [Hentry [Hidle Hnon_idle]].
  assert (Hentered : entered_caller = FlagPendTaskCaller entered).
  { destruct entered_caller as [actual|view active];
      cbn [PendPhaseCandidate.flag_pend_caller_save_observation] in PreH3; intuition congruence. }
  subst entered_caller.
  cbn [PendPhaseCandidate.flag_pend_caller_save_observation] in PreH3.
  destruct PreH3 as [_ [_ [Hsave [Hsame Hpreserved]]]].
  assert (Hsave_counters : before.(IntrState) = acquired.(IntrState)).
  { exact (PendSchedulerSeedAdapter.flag_pend_task_source_observations_interrupts_eq environment sg call before entered acquired (flag_pend_task_entry_call_source call before Hentry) PreH4). }
  assert (Hsaved : flag_pend_saved_prefix environment critical sg call mask before i pgrp0
    entered joined_saved acquired).
  { unfold flag_pend_saved_prefix.
    refine (conj PreH10 (conj PreH11 (conj PreH12 (conj _ (conj Hsave (conj PreH18 (conj Hsame Hsave_counters))))))).
    exists observed; split; assumption. }
  assert (Hready_before : flag_pend_current_ready call before).
  { destruct Hentry as [[_ [_ [_ [old [Hready [Hgen Hclean]]]]]] _].
    exists old; auto. }
  pose proof (flag_pend_task_entry_call_source call before Hentry) as Hcall_source.
  cbn [flag_pend_call_source_observations] in PreH4.
  destruct PreH4 as [Hready_after [Hidle_after [Hnon_idle_after Hcontrol_caller]]].
  pose proof (PendPhaseCandidate.flag_pend_caller_return_control_task_source
    call before entered acquired Hcall_source Hcontrol_caller) as Hcontrol.
  specialize (Hready_after (conj Hcall_source Hready_before)).
  specialize (Hidle_after (conj Hcall_source Hidle)).
  specialize (Hnon_idle_after (conj Hcall_source Hnon_idle)).
  assert (Hrunning : flag_pend_running_available entered acquired).
  { eapply flag_pend_return_control_running_available; [exact Hcontrol|].
    apply flag_pend_task_stage_running_available; exact (proj1 Hentry). }
  assert (Hfresh : flag_active_fresh_registration call entered acquired).
  { apply PreH19; left; exact Hvalid_mode. }
  assert (Hstage : flag_pend_task_stage entered acquired).
  { eapply flag_pend_fresh_ready_task_stage; eassumption. }
  assert (Hnon_idle_original : flag_pend_non_idle_at sg call acquired).
  { unfold flag_pend_non_idle_at in *.
    rewrite (proj2 (proj2 Hsame)) in Hnon_idle_after; exact Hnon_idle_after. }
  assert (Hblock_source : flag_pend_block_source_facts sg call entered acquired).
  { unfold flag_pend_block_source_facts; tauto. }
  assert (Hflags : valid_flag_state sg acquired.(FlagState)).
  { unfold UCOS2_state_inv, UCOS2_state_inv_with_ready in PreH22.
    assert (Hflags_config : valid_flag_configuration sg acquired.(FlagState)) by tauto.
    unfold valid_flag_configuration in Hflags_config.
    rewrite Hconfig in Hflags_config; exact Hflags_config. }
  destruct (flag_pend_group_type_five_implies_live__block_prepare_base sg acquired.(FlagState) i protected_image
    Hflags PreH23 PreH25) as [group Hgroup].
  destruct Hready_after as [old_task [Htask_ready Htaskgen]].
  pose proof (proj1 Htask_ready) as Hold.
  assert (Hnode_nonzero : (&("node")) <> 0) by apply CNotation.addr_of_LE_var_not_zero.
  prop_apply_p (flag_pend_local_node_not_registered__block_prepare_base sg acquired (&("node")) Hconfig).
  Intros.

  rename H into Habsent.
  set (waiter := {| flagNodeAddr := &("node");
    flagTask := entered.(os_sched_call_stack).(stackLeaseSlot);
    flagTaskGeneration := old_task.(taskGeneration);
    flagGroup := i; flagGroupGeneration := group.(flagGeneration);
    flagMask := requested; flagWaitMode := FlagSetAny;
    flagWaitImage := {| flagNodeNext := 0; flagNodePrev := 0; flagNodeTCB := 0;
      flagNodeGroup := 0; flagNodeMask := 0; flagNodeMode := 0;
      flagNodePadding := (None :: nil) |} |}).
  assert (Hprotocol : flag_block_call_protocol sg acquired waiter old_task group protected_image delay).
  { apply (flag_pend_stage_block_protocol sg acquired entered waiter old_task group protected_image delay);
      try assumption; try reflexivity.
    - unfold waiter; cbn [flagMask]; unfold flag_word_in_range.
      rewrite Hconfig; exact Hrequested.
    - lia. }
  assert (Hbinding : flag_pend_block_binding sg call entered acquired i &("node")
    requested joined_mode delay waiter old_task group protected_image).
  { unfold flag_pend_block_binding.
    split; [exact Hfresh|].
    split.
    - unfold task_stack_key; rewrite <- (proj2 (proj2 Hsame)); cbn [waiter flagTask flagTaskGeneration].
      rewrite Htaskgen; reflexivity.
    - split; [exact Hprotocol|].
      cbn [waiter flagNodeAddr flagGroup flagMask flagWaitMode encode_flag_wait_mode]; intuition. }

  assert (Hunsatisfied : flag_pend_first_unsatisfied sg protected_image requested original_mode).
  { exists FlagSetAny; split.
    - unfold decode_flag_wait_mode; destruct PreH24 as [Hnormalized _].
      rewrite <- Hnormalized, <- PreH27; reflexivity.
    - cbn [flag_wait_satisfied flag_ready_bits].
      rewrite (flag_pend_word_land_requested_eq__block_prepare_base sg _ requested Hconfig Hrequested).
      rewrite unsigned_last_nbits_eq in PreH1 by exact Hrequested.
      change (Z.land protected_image.(flagImageBits) requested = 0) in PreH1.
      rewrite PreH1; reflexivity. }
  assert (Hpgrp : pgrp0 = flag_block_call_group sg waiter).
  { destruct Hslot as [Hzero|[_ Heq]]; [contradiction|exact Heq]. }
  assert (Hnormalized : joined_mode = flag_block_call_mode waiter).
  { unfold flag_block_call_mode; cbn [waiter flagWaitMode encode_flag_wait_mode]; lia. }
  assert (Hcur : &("OSTCBCur") = sg.(g_OSTCBCur)) by exact (proj2 PreH8).
  assert (Hreadytbl : &("OSRdyTbl") = sg.(g_OSRdyTbl)).
  { destruct PreH8 as [Hglobal _]; unfold os_sched_global_addresses, sched_new_global_addresses in Hglobal; tauto. }
  assert (Hreadygrp : &("OSRdyGrp") = sg.(g_OSRdyGrp)).
  { destruct PreH8 as [Hglobal _]; unfold os_sched_global_addresses, sched_new_global_addresses in Hglobal; tauto. }
  Exists waiter old_task group.
  unfold flag_block_call_fields_pre, flag_pend_block_callee_frame.
  cbn [flag_pend_caller_masked_control].
  unfold flag_pend_node_fields.
  rewrite Hconfig.
  entailer!.
  exact (proj1 PreH6).
Qed.

