  assert (Hprefix : flag_pend_saved_prefix environment critical sg call mask before
    i pgrp0 entered joined_saved acquired).
  { unfold flag_pend_saved_prefix.
    split; [exact PreH12|]. split; [exact PreH13|]. split; [exact PreH14|].
    split; [exists observed; auto|].
    split; [exact Hsave|]. split; [assumption|].
    exact (conj Hsame Hsave_counters). }
  assert (Hfresh : flag_active_fresh_registration call entered acquired).
  { apply PreH21; left; exact Hmode_valid. }
  assert (Hready_before : flag_pend_current_ready call before).
  { destruct (proj1 Hentry) as [_ [_ [_ [node [Hready [Hgen Hclean]]]]]].
    exists node; auto. }
  assert (Hstage : flag_pend_task_stage entered acquired).
