      + exact Hready_before.
    - apply (flag_pend_return_control_running_available call before entered acquired).
      + exact (PendPhaseCandidate.flag_pend_caller_return_control_task_source
          call before entered acquired (flag_pend_task_entry_call_source call before Hentry)
          (proj2 (proj2 (proj2 PreH6)))).
      + apply flag_pend_task_stage_running_available; exact (proj1 Hentry). }
  assert (Hrequested_cast : unsigned_last_nbits requested 16 = requested).
  { apply unsigned_last_nbits_eq; exact Hrequested. }
  rewrite Hrequested_cast in PreH3 |- *.
  assert (Htestbit : Z.testbit original_mode 7 = true).
