  pose proof (flag_pend_group_current_merge_ready_flags__immediate_clear_2
    sg acquired current_tid current_task i protected_image ready bits true
    Hconfig PreH24 PreH1 PreH25 PreH27 Hbits) as Hfields.
  cbn beta iota zeta in Hfields; fold post_flags post in Hfields.
  destruct PreH8 as [_ [_ [Htype_layout [Hbits_layout [Hready_layout Hrest_layout]]]]].
  destruct PreH10 as [_ Hcurrent_address].
  rewrite Htype_layout, Hbits_layout, Hready_layout, Hcurrent_address, Haddress.
  unfold flag_pend_group_type, flag_pend_group_bits.
  fold ready bits; sepcon_assoc_change; sep_apply_l_atomic Hfields.
  unfold flag_pend_caller_masked_control; Intros.
  pose proof (flag_pend_ready_flags_control__immediate_clear_2
