    current_tid current_task ready post_flags (proj2 PreH1)) as Hcontrol.
  fold post in Hcontrol; sep_apply_l_atomic Hcontrol.
  assert (Hreturned_entry : FlagPendEntryControl.flag_pend_active_entry sg
    (flag_pend_first_observation original_mode call before) post).
  { apply FlagPendEntryControl.FlagPendEntryFirst; intros _.
    match goal with
    | Hstage : flag_pend_task_stage _ post |- _ => exact (proj1 (proj2 Hstage))
    end. }
  assert (Hreturned_counters : os_sched_ints post = 0 /\ os_sched_locks post = 0).
  { eapply FlagPendCounterEntry.flag_pend_first_critical_counters_zero; [eassumption| |].
    all: match goal with
    | Hprefix : flag_pend_saved_prefix _ _ _ _ _ _ _ _ _ _ ?acquired_state |- _ =>
      destruct Hprefix as [_ [Hint [Hlock [_ [_ [_ [_ Heq]]]]]]];
      unfold os_sched_ints, os_sched_locks in *; rewrite Heq in Hint, Hlock; lia
    end. }
  destruct Hreturned_counters as [Hreturned_ints Hreturned_locks].
  Exists post.
  rewrite (flag_pend_caller_masked_fields_split environment critical acquired_local sg
    (FlagPendTaskCaller entered) entered joined_saved acquired post).
  unfold flag_pend_caller_masked_control; entailer!.
  all: rewrite <- Haddress; assumption.
Qed.

