  2: { destruct Hsource as [_ Hfalse].
       exact (False_ind _ (Hfalse PreH12 PreH13 PreH14 observed PreH16 PreH17 Hvalidmode)). }
  destruct Hsource as [Hactual Hdomain]; subst actual.
  destruct (Hdomain PreH12 PreH13 PreH14 observed PreH16 PreH17 Hvalidmode)
    as [Hentry [Hidle Hnonidle]].
  destruct entered_caller as [actual|view key].
  2: { contradiction. }
