      (conj (ex_intro _ observed (conj PreH16 PreH17))
        (conj Hsave (conj PreH20 (conj Hsame (PendSchedulerSeedAdapter.flag_pend_task_source_observations_interrupts_eq environment sg call before entered acquired (flag_pend_task_entry_call_source call before Hentry) PreH6)))))))). }
  assert (Hbefore_ready : flag_pend_current_ready call before).
  { destruct Hentry as [[_ [_ [_ [node [Hready [Hgen Hclean]]]]]] _].
    exists node; auto. }
  destruct PreH6 as [Hready_source [Hidle_source [Hnonidle_source Hcontrol_source_caller]]].
  pose proof (PendPhaseCandidate.flag_pend_caller_return_control_task_source
    call before entered acquired (flag_pend_task_entry_call_source call before Hentry) Hcontrol_source_caller) as Hcontrol_source.
  pose proof (Hready_source (conj (flag_pend_task_entry_call_source call before Hentry) Hbefore_ready))
    as Hacquired_ready.
  pose proof (flag_pend_return_control_running_available call before entered acquired Hcontrol_source
    (flag_pend_task_stage_running_available call before (proj1 Hentry))) as Havailable.
