  pose proof (flag_pend_fresh_ready_task_stage call entered acquired Hfresh Hacquired_ready Havailable) as Hstage.
  assert (Hrequested_cast : unsigned_last_nbits requested 16 = requested).
  { apply unsigned_last_nbits_eq; exact Hrequested. }
  rewrite Hrequested_cast in *.
  set (bits := flag_pend_group_bits protected_image).
  set (ready := Z.land (Z.lnot bits) requested).
  fold bits in PreH3 |- *.
  fold ready in PreH3 |- *.
  assert (Hbits : 0 <= bits < 65536).
  { pose proof PreH24 as [_ [_ [_ [_ [_ [_ [_ [Hflags _]]]]]]]].
    unfold valid_flag_configuration in Hflags; rewrite Hconfig in Hflags.
    cbn [selected_kernel_configuration cfgFlagEnabled] in Hflags.
    destruct Hflags as [_ [_ [Himages _]]].
    pose proof (proj1 (Himages i protected_image PreH25)) as Hbound.
    unfold flag_word_in_range in Hbound; rewrite Hconfig in Hbound; exact Hbound. }
  assert (Hbits_cast : unsigned_last_nbits bits 16 = bits).
  { apply unsigned_last_nbits_eq; exact Hbits. }
  rewrite Hbits_cast.
  assert (Hready_value : flag_ready_bits sg.(osKernelConfig) bits requested FlagClearAny = ready).
  { unfold flag_ready_bits, flag_word; rewrite Hconfig.
    change (unsigned_last_nbits (Z.land (Z.lnot bits) requested) 16 = ready).
    unfold ready; apply unsigned_last_nbits_land_missing_r; lia. }
  assert (Hready_range : 0 <= ready < 65536).
  { pose proof (flag_word_bounds sg.(osKernelConfig) (Z.land (Z.lnot bits) requested)
      ltac:(rewrite Hconfig; cbn; lia)) as Hr.
    change (flag_word_in_range sg.(osKernelConfig)
      (flag_ready_bits sg.(osKernelConfig) bits requested FlagClearAny)) in Hr.
    rewrite Hready_value in Hr; unfold flag_word_in_range in Hr; rewrite Hconfig in Hr; exact Hr. }
  assert (Hconsume_value : flag_consume_bits sg.(osKernelConfig) bits ready FlagClearAny = Z.lor bits ready).
  { unfold flag_consume_bits, flag_word; rewrite Hconfig.
    change (unsigned_last_nbits (Z.lor bits ready) 16 = Z.lor bits ready).
    apply unsigned_last_nbits_lor_distr_missing; lia. }
  assert (Hconsumed : Z.testbit original_mode 7 = true).
  { pose proof (flag_pend_mode_consume_testbit_eq__immediate_clear_3 _ _ _ PreH26) as H.
    destruct (Z.testbit original_mode 7); [reflexivity|].
    rewrite H in PreH2; vm_compute in PreH2; discriminate. }
  assert (Hdecode : decode_flag_wait_mode sg.(osKernelConfig) (Z.land original_mode 127) = Some FlagClearAny).
  { rewrite Hconfig, Hmode; reflexivity. }
  assert (Hsatisfied : flag_wait_satisfied FlagClearAny ready requested = true).
  { unfold flag_wait_satisfied; apply Bool.negb_true_iff, Z.eqb_neq; exact PreH3. }
  pose proof PreH1 as [Hcurrent Hold].
  pose proof (flag_pend_first_ready sg i requested original_mode delay acquired FlagClearAny
    protected_image current_tid current_task Hdecode PreH25 PreH27) as Hstep.
  change (let r := flag_ready_bits sg.(osKernelConfig) bits requested FlagClearAny in
    flag_wait_satisfied FlagClearAny r requested = true ->
    acquired.(SchedState).(curTaskID) = Some current_tid ->
    acquired.(TskState).(inUsedTaskStates) current_tid = Some current_task ->
    flag_pend_first_critical sg i requested original_mode delay acquired (FlagPendReturn r 0)
      (flag_pend_update_task
        (if Z.testbit original_mode 7 then replace_FlagS
           (flag_pend_pool_set_bits acquired.(FlagState) i protected_image
             (flag_consume_bits sg.(osKernelConfig) bits r FlagClearAny)) acquired else acquired)
        current_tid (flag_pend_task_set_ready_flags current_task r))) in Hstep.
  rewrite Hready_value in Hstep; cbv zeta in Hstep.
  rewrite Hconsumed, Hconsume_value in Hstep.
  specialize (Hstep Hsatisfied Hcurrent Hold).
  set (flags := flag_pend_pool_set_bits acquired.(FlagState) i protected_image (Z.lor bits ready)).
  set (new_image := flag_image_set_bits protected_image (Z.lor bits ready)).
  set (released := flag_pend_update_task (replace_FlagS flags acquired) current_tid
    (flag_pend_task_set_ready_flags current_task ready)).
  assert (Hvalid : UCOS2_state_inv sg released).
  { unfold released; apply flag_pend_ready_flags_preserves_validity__immediate_clear_3 with (old:=current_task);
      [|exact Hold].
    unfold flags; apply flag_pend_live_bits_preserves_validity__immediate_clear_3;
      [rewrite Hconfig; reflexivity|exact PreH24|exact PreH25|exact PreH27|].
    rewrite <- Hconsume_value; apply flag_consume_bits_in_range; rewrite Hconfig; cbn; lia. }
  assert (Hreleased_stage : flag_pend_task_stage entered released).
  { apply flag_pend_ready_flags_stage_preserved__immediate_clear_3; assumption. }
  assert (Hregistration : flag_pend_first_registration original_mode call before entered released).
  { intros _; apply flag_pend_ready_flags_registration_preserved__immediate_clear_3; assumption. }
  assert (Hnew : flags.(flagImages) i = Some new_image).
  { apply flag_pend_pool_set_bits_image. }
  assert (Himages : forall j, j <> i -> acquired.(FlagState).(flagImages) j = flags.(flagImages) j).
  { intros j Hj; symmetry; apply Ucos2Verify.lib.kernel_resources.kernel_map_set_other; exact Hj. }
  pose proof (flag_pend_ready_flags_merge_group__immediate_clear_3 sg acquired current_tid current_task i
    protected_image flags new_image ready Hconfig PreH1 Hnew Himages eq_refl eq_refl eq_refl Hvalid) as Hmerge.
  cbn [new_image flag_image_set_bits flagImageType flagImageBits] in Hmerge.
  pose proof (flag_pend_ready_flags_control_transport__immediate_clear_3 environment acquired_local critical sg
    (FlagPendTaskCaller entered) entered joined_saved acquired acquired flags current_tid current_task ready Hold) as Htransport.
  fold released in Hmerge, Htransport.
  assert (Hreturned_entry : FlagPendEntryControl.flag_pend_active_entry sg
    (flag_pend_first_observation original_mode call before) released).
  { apply FlagPendEntryControl.FlagPendEntryFirst; intros _.
    match goal with
    | Hstage : flag_pend_task_stage _ released |- _ => exact (proj1 (proj2 Hstage))
    end. }
  assert (Hreturned_counters : os_sched_ints released = 0 /\ os_sched_locks released = 0).
  { eapply FlagPendCounterEntry.flag_pend_first_critical_counters_zero; [eassumption| |].
    all: match goal with
    | Hprefix : flag_pend_saved_prefix _ _ _ _ _ _ _ _ _ _ ?acquired_state |- _ =>
      destruct Hprefix as [_ [Hint [Hlock [_ [_ [_ [_ Heq]]]]]]];
      unfold os_sched_ints, os_sched_locks in *; rewrite Heq in Hint, Hlock; lia
    end. }
  destruct Hreturned_counters as [Hreturned_ints Hreturned_locks].
  Exists released.
  assert (Hfirst : flag_pend_first_return sg i requested original_mode delay acquired ready 0 released) by exact Hstep.
  entailer!.
  destruct PreH8 as [_ [_ [Htype [Hflagfield [Htaskfield _]]]]].
  destruct PreH10 as [_ Hcuraddr].
  assert (Hpgrp : pgrp0 = flag_pool_addr sg i) by tauto.
  rewrite Htype, Hflagfield, Htaskfield, Hcuraddr, Hpgrp.
  unfold flag_pend_group_type.
  sepcon_assoc_change.
  sep_apply_l_atomic Hmerge.
  sep_apply_l_atomic Htransport.
  sep_apply_r_atomic (proj2 (flag_pend_caller_masked_fields_split environment critical acquired_local sg
    (FlagPendTaskCaller entered) entered joined_saved acquired released)).
  entailer!.
Qed.

