  destruct PreH4 as [Hready_after [Hidle_after [Hnon_idle_after Hcontrol_caller]]].
  pose proof (PendPhaseCandidate.flag_pend_caller_return_control_task_source
    call before entered acquired Hcall_source Hcontrol_caller) as Hcontrol.
