  pose proof (proj1 Htask_ready) as Hold.
  assert (Hnode_nonzero : (&("node")) <> 0) by apply CNotation.addr_of_LE_var_not_zero.
  assert (Hlocal_absent : UCOS2_fields_inv sg acquired ** flag_pend_node_fields (&("node")) |--
    coq_prop (acquired.(FlagState).(flagWaitNodes) (&("node")) = None)).
  { unfold UCOS2_fields_inv, UCOS2_fields_raw_rep, flag_fields_configured_rep.
