    intros key payload updated Hlookup Hupdated Hgen.
    exact (Hfields _ _ Hupdated Hold). }
  assert (Hblocked_guards :
    os_sched_ints (flag_block_state acquired waiter flags old_task delay) <= 0 /\
    os_sched_locks (flag_block_state acquired waiter flags old_task delay) <= 0).
  { change (os_sched_ints acquired <= 0 /\ os_sched_locks acquired <= 0).
