Lemma proof_of_OSFlagPend_entail_wit_20 : flag_pend_goal.OSFlagPend_entail_wit_20.
Proof.
  left; intros.
  retain_original_public_entry__active_tick.
  set (environment := task_sw_hook_call_environment base_environment) in *.
  assert (Hsource : flag_pend_caller_save_input environment critical scheduled_local
    (flag_pend_wait_active sg call (&("node"))) sg (FlagPendTaskCaller scheduled_call)
    scheduled_call mask scheduled_state |-- coq_prop (task_resume_spec.kernel_call_task_source scheduled_call scheduled_state)).
  {
    unfold flag_pend_caller_save_input, flag_pend_active_save_input,
      flag_pend_wait_active, flag_active_phase_source_spec.flag_active_waiting.
    Intros.
    entailer!.
    destruct H1 as [old [Hfields Hnode]].
    destruct Hfields as [[Hinv_eq [Horigin_eq Hstack_eq]]
      [Horigin [Hlookup [Hgen [Hinv Hclear]]]]].
    unfold task_resume_spec.kernel_call_task_source.
    split; [rewrite Horigin_eq, Hstack_eq; exact Horigin |].
    split; [rewrite Hinv_eq, Horigin_eq; exact Hinv |].
    unfold task_resume_spec.task_execution_current; rewrite Horigin_eq, Horigin.
    destruct PreH6 as [task [[Hlookup2 [Hcur Hrest]] Hgen2]].
    rewrite Hstack_eq in Hcur; exact Hcur.
  }
  assert (Hopen : SelectedCallerPhaseComponent.flag_pend_selected_caller_save_output environment critical scheduled_local
    (flag_pend_wait_active sg call (&("node"))) sg (FlagPendTaskCaller scheduled_call)
    scheduled_call mask scheduled_state second_heap retval |--
    EX returned_caller reentered reacquired resumed_local,
    coq_prop (PendPhaseCandidate.flag_pend_caller_save_observation environment critical sg (FlagPendTaskCaller scheduled_call)
      scheduled_call returned_caller reentered mask retval scheduled_state reacquired /\
      interrupt_saved_value mask retval /\
      flag_pend_call_source_observations environment sg (FlagPendTaskCaller scheduled_call)
        scheduled_call scheduled_state reentered reacquired /\
      task_resume_spec.kernel_call_task_source scheduled_call scheduled_state) &&
    flag_pend_caller_restore_input environment critical resumed_local
      (flag_pend_wait_active sg call (&("node"))) sg returned_caller reentered retval reacquired reacquired).
  {
    intros heap [rc [re [ac [lo [Hobs [Hsaved [Hbefore [Hafter Hcompleted]]]]]]]].
    exists rc, re, ac, lo; split; [|exact Hafter].
    pose proof (proj1 (CompletedCallerSource.flag_pend_selected_completed_source_endpoints
      _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hcompleted)) as Hendpoint.
    assert (Hsource_observations : flag_pend_call_source_observations environment sg
      (FlagPendTaskCaller scheduled_call) scheduled_call scheduled_state re ac).
    { destruct Hendpoint as [Hready_endpoint [Hidle_endpoint [Hnonidle_endpoint [Hnormal Hcontrol_endpoint]]]].
      split; [exact Hready_endpoint|]. split; [exact Hidle_endpoint|].
      split; [exact Hnonidle_endpoint|]. split; [exact Hnormal|].
      intro Horigin. eapply flag_pend_normal_return_control;
        [exact Hnormal|exact (Hcontrol_endpoint Horigin)]. }
    exact (conj Hobs (conj Hsaved (conj
      Hsource_observations
      (Hsource second_heap Hbefore)))).
  }
  rewrite Hopen.
  Intros returned_caller reentered reacquired resumed_local.
  destruct H as [Hobs [Hsaved [Hobservations Hscheduled_source]]].
  destruct returned_caller as [next|view key]; [|contradiction].
  destruct Hobs as [Heq [Hnext [Heffect [Hsame Htransport]]]]; subst next.
  destruct Hobservations as [Hready_transport [Hidle [Hnonidle Hcontrol_caller]]].
  pose proof (PendPhaseCandidate.flag_pend_caller_return_control_task_source
    scheduled_call scheduled_state reentered reacquired Hscheduled_source Hcontrol_caller) as Hcontrol.
  pose proof (Hready_transport (conj Hscheduled_source PreH6)) as Hready.
  pose proof (flag_pend_return_control_running_available _ _ _ _ Hcontrol PreH7) as Hrunning.
  destruct (FlagPendCounterEntry.flag_pend_return_control_counters_zero
    _ _ _ _ Hcontrol PreH9 PreH10) as [Hreacquired_ints Hreacquired_locks].
  assert (Hprefix : flag_pend_resumed_prefix environment critical sg call mask before i pgrp0
    requested original_mode delay (&("node")) reentered retval reacquired).
  { exists scheduled_call, scheduled_state; auto. }
  destruct Hready as [resume_task [Hready_task Hgen]].
  assert (Hbinding : flag_pend_current_binding reacquired
    reentered.(os_sched_call_stack).(stackLeaseSlot) resume_task).
  { split; [exact (proj1 (proj2 Hready_task))|exact (proj1 Hready_task)]. }
  assert (Hready : flag_pend_current_ready reentered reacquired).
  { exists resume_task; auto. }
  assert (Hsplit : flag_pend_caller_restore_input environment critical resumed_local
    (flag_pend_wait_active sg call (&("node"))) sg (FlagPendTaskCaller reentered)
    reentered retval reacquired reacquired |--
    flag_pend_masked_control environment resumed_local critical sg reentered retval reacquired reacquired **
    UCOS2_fields_inv sg reacquired ** flag_pend_wait_active sg call (&("node")) reentered reacquired).
  { unfold flag_pend_caller_restore_input, flag_pend_active_restore_input,
      os_sched_fields_restore_input, flag_pend_masked_control; entailer!. }
  rewrite Hsplit.
  Exists resumed_local reentered.(os_sched_call_stack).(stackLeaseSlot) resume_task reentered reacquired.
  pose proof (flag_pend_resume_fields_split sg reacquired
    reentered.(os_sched_call_stack).(stackLeaseSlot) resume_task (proj1 Hlegacy_entry__active_tick) Hbinding) as Hfields.
  pose proof PreH1 as Hlayout.
  destruct Hlayout as [Hblock [Hunlink [Htype [Hbits [Hrdy [Hstat [Hpend Hstack]]]]]]].
  destruct PreH3 as [Haddresses Hcurrent_address].
  rewrite <- Hcurrent_address in Hfields.
  rewrite <- Hpend, <- Hstat in Hfields.
  sep_apply_l_atomic Hfields.
  unfold flag_pend_wait_active; Intros.
  entailer!.
  exact (conj Haddresses Hcurrent_address).
Qed.

Lemma proof_of_OSFlagPend_entail_wit_21 : flag_pend_goal.OSFlagPend_entail_wit_21.
Proof.
  left; intros.
  retain_original_public_entry__active_tick.
  pose proof (proj1 Hlegacy_entry__active_tick) as Hconfig.
  pose proof (proj2 PreH7) as Hcurrent_address.
  pose proof PreH5 as [Hblocklayout [Hunlinklayout [Htype [Hbits [Hflags [Hstat [Hpend Hsp]]]]]]].
  assert (Hstatus : statPend resume_task = PendTimeout).
  { destruct (statPend resume_task); vm_compute in PreH1, PreH2 |- *; congruence. }
  unfold flag_pend_wait_active, flag_active_waiting; Intros.
  repeat match goal with H : _ /\ _ |- _ => destruct H end.
  match goal with Hr : flag_active_waiting_registration call _ reentered reacquired |- _ =>
    pose proof Hr as Hregistration;
    pose proof (flag_pend_waiting_current_task__resume_error call reentered &("node")
