  rewrite Hwaiter in Hnode; destruct Hnode as [Haddr [Hkey Hptr]].
  assert (Hw : flagTask waiter = current_tid).
  { unfold task_stack_key in Hkey; inversion Hkey; congruence. }
  assert (Hinv : UCOS2_state_inv sg reacquired) by assumption.
  pose proof Hinv as [_ [Htaskrange [_ [_ [Hcross [_ [_ [Hflag _]]]]]]]].
  unfold valid_flag_configuration in Hflag; rewrite Hconfig in Hflag.
  pose proof Hcross as [_ [_ [_ [_ [_ [Hconsistency _]]]]]].
  destruct (proj1 Hconsistency &("node") waiter Hwaiter)
    as [_ [found [Hfound [Hgen [Hptr2 [Htcb Hrest]]]]]].
  rewrite Hw in Hfound.
  pose proof (proj2 PreH12) as Hold.
  rewrite Hold in Hfound; inversion Hfound; subst found.
  pose proof (task_active_lookup_identity__resume_error sg (TskState reacquired)
    current_tid resume_task Htaskrange Hold) as Hid.
  assert (Hmerge :
    tcb_field_address (task_slot_addr sg current_tid) TCBStatPend # UChar |-> 0 **
    tcb_field_address (task_slot_addr sg current_tid) TCBStat # UChar |-> encode_task_status (stat resume_task) **
    task_public_storage_without_two_fields sg (TskState reacquired) current_tid resume_task
      (TCBCommonField TCBStatPend) (TCBCommonField TCBStat) |--
    used_task_rep sg current_tid (flag_pend_write_pend_ok resume_task) **
    task_public_storage_without_task sg (TskState reacquired) current_tid).
  { exact (flag_pend_resume_merge_written_pend__resume_error
      sg (TskState reacquired) current_tid resume_task). }
  rewrite Hpend, Hstat.
  unfold flag_pend_resume_frame.
  sepcon_assoc_change; sep_apply_l_atomic Hmerge.
  sep_apply_l_atomic (proj1 (used_task_rep_tcb64 sg current_tid (flag_pend_write_pend_ok resume_task)
    ltac:(rewrite Hconfig; reflexivity) ltac:(rewrite Hconfig; reflexivity))).
  Exists waiter.
  unfold flag_unlink_fields_pre, flag_pend_unlink_callee_frame, flag_pend_unlink_frame,
    flag_unlink_task_rep, flag_continuation_fields_resources_spec.flag_pend_sched_node_fields_rep.
  rewrite Hwaiter, Hw.
  rewrite (task_slot_addr_tcb64 sg current_tid ltac:(rewrite Hconfig; reflexivity)
    ltac:(rewrite Hconfig; reflexivity)).
  entailer!.
  - unfold flag_unlink_domain; cbn [flag_pend_write_pend_ok task_set_status task_clear_pend_status taskID taskGeneration tcbFlagNode].
    split; [exact Hconfig|]. split; [exact Hflag|]. split; [exact Hwaiter|].
    split; [exact Haddr|]. split; [congruence|]. split; [exact Hgen|].
    split; assumption.
  - unfold flag_pend_timeout_waiter_binding; auto.
  - rewrite Hstatus; simpl; discriminate.
  - unfold flag_pend_error_source_facts.
    refine (conj PreH11 (conj PreH12 (conj PreH13 (conj PreH14 (conj PreH15 (conj Hregistration _)))))).
    rewrite Hstatus; simpl; discriminate.
